["(40% of Damage from Suppressed Hits and Ailments they inflict is prevented)"]="(억제된 명중과 상태 이상으로 받는 피해의 40%를 방지합니다.)",
["(A torrent rushes upwards after a short delay, dealing damage in an area while leaving Brine Ground)"]="(잠시 후 급류가 솟구쳐 오르며, 범위 내에 피해를 주고 염수 지대를 남깁니다.)",
["(Adrenaline grants 100% increased Damage, 25% increased Attack, Cast and Movement Speed and 10% additional Physical Damage Reduction. You cannot gain Adrenaline if you already have it)"]="(\"아드레날린\"이 주는 피해를 100% 증가시키고 공격, 시전 및 이동 속도를 25% 증가시킵니다. 또한 받는 물리 피해를 10% 추가로 감소시킵니다. 이미 아드레날린이 있는 경우 획득할 수 없습니다.)",
["(Affects Melee Strikes, including the Default Attack. Does not apply to Areas of Effect)"]="(기본 공격을 포함한 근접 타격에 영향을 줍니다. 범위 효과에는 적용되지 않습니다)",
["(Ailments are Bleeding, Ignited, Scorched, Chilled, Frozen, Brittle, Shocked, Sapped, and Poisoned)"]="(상태 이상 - 출혈, 점화, 그을림, 냉각, 동결, 허약, 감전, 활력 감소, 중독)",
