["(Ailments that do not deal Damage are Scorched, Chilled, Frozen, Brittle, Shocked, and Sapped)"]="(피해를 가하지 않는 상태 이상 - 그을림, 냉각, 동결, 허약, 감전, 활력 감소)",
["(Alchemist's Genius increases Flask Charges gained by 20% and effect of Flasks by 10%, for 4 seconds)"]="(연금술사의 천재성이 4초 동안 플라스크 충전량을 20%, 플라스크의 효과를 10% 증가시킵니다.)",
["(Allies on your Consecrated Ground Regenerate a percentage of their Maximum Life per second, and Curses have 50% reduced effect on them)"]="(\"신성화 지대\"에서는 동료의 생명력이 1초당 최대 생명력의 정해진 비율만큼 차오르며, 동료에게 적용되는 저주의 효과가 50% 감소합니다.)",
["(Allies on your Fungal Ground have +25% to Chaos Resistance. Enemies on your Fungal Ground have -10% to all Resistances.)"]="(플레이어가 생성한 곰팡이 지대에 있는 동료는 카오스 저항에 +25%가 적용됩니다. 플레이어가 생성한 곰팡이 지대에 있는 적은 모든 저항에 -10%가 적용됩니다.)",
["(Arcane Might causes Increases and Reductions to Spell Damage to also apply to Attack Damage at that percentage of their value)"]="(비전 완력은 주문 피해에 적용되는 증가 및 감소 효과를 그 수치의 해당 비율만큼 공격 피해에도 적용시킴)",
["(Arcane Surge grants 20% increased Cast Speed and 30% increased Mana Regeneration rate)"]="(\"비전 쇄도\"가 시전 속도를 20% 증가시키고, 마나 재생 속도를 30% 증가시킵니다)",
["(Arcane Surge grants 20% increased Cast Speed and 30% increased Mana Regeneration rate, for 4 seconds)"]="(\"비전 쇄도\"가 시전 속도를 20% 증가시키고, 마나 재생 속도를 30% 증가시킵니다. 4초 동안 유지됩니다)",
["(Armour is treated as this percentage of its actual value, only for calculating damage mitigation)"]="(완화되는 피해를 계산하는 경우에 한해 방어도를 원래 수치의 해당 퍼센트로 간주)",
["(Armour, Evasion Rating and Energy Shield are the standard Defences)"]="(방어는 일반적으로 방어도, 회피, 에너지 보호막으로 구성됩니다)",
["(Attacks made against Enemies affected by Hallowing Flame gain 25% of Physical Damage as Extra Fire Damage."]="(거룩한 불길의 영향을 받는 적에게 가하는 공격이 물리 피해의 25%를 추가 화염 피해로 획득합니다.",
["(Attributes are Strength, Dexterity, and Intelligence)"]="(\"능력치\"는 힘, 민첩, 지능입니다)",
