["(Being Blinded causes 20% less Accuracy Rating and Evasion Rating, for 4 seconds)"]="(실명은 4초 동안 정확도와 회피를 20% 감폭시킵니다.)",
["(Being Covered in Ash applies 20% less Movement Speed and 20% increased Fire Damage Taken)"]="(\"재로 뒤덮임\" 상태에서는 이동 속도가 20% 감폭되고 받는 화염 피해가 20% 증가합니다.)",
["(Being Covered in Ash applies 20% less Movement Speed and 20% increased Fire Damage Taken, for 4 seconds)"]="(\"재로 뒤덮임\" 상태에서는 이동 속도가 20% 감폭되고 받는 화염 피해가 20% 증가합니다. 4초 동안 유지됩니다)",
["(Bleeding deals Physical Damage over time, based on the base Physical Damage of the Skill. Damage is 200% higher while moving)"]="(\"출혈\"은 지속 물리 피해를 주며, 피해량은 해당 스킬의 기본 물리 피해에 의해 결정됩니다. 출혈 피해는 이동할 때 200% 더 높아집니다)",
["(Bleeding which has been Aggravated always deals higher Damage as though the target was moving)"]="(가중된 출혈은 항상 대상이 이동 중이었던 것처럼 더 많은 피해를 줍니다.)",
["(Brand Critical Strikes are any Critical Strikes dealt by Brand Skills or by Skills Triggered by a Brand)"]="(낙인 치명타란 낙인 스킬 또는 낙인으로 인해 발동하는 스킬이 주는 치명타입니다.)",
["(Brand Damage is any Damage dealt by Brand Skills or by Skills Triggered by a Brand)"]="(낙인 피해란 낙인 스킬이나 낙인으로 인해 발동하는 스킬이 주는 피해입니다.)",
