["(Chaotic Might grants 30% of Physical Damage as extra Chaos Damage)"]="('혼돈의 완력'은 물리 피해의 30%를 추가 카오스 피해로 가합니다)",
["(Characters inherently gain +12 Life per Level)"]="(캐릭터가 기본적으로 1레벨당 생명력 +12 획득)",
