["(Crushed lowers Physical Damage Reduction by 15% for 4 seconds)"]="(타쇄당함이 물리 피해 감소를 4초 동안 15% 낮춤)",
["(Crushed lowers Physical Damage Reduction by 15%)"]="(타쇄당함이 물리 피해 감소를 15% 낮춤)",
["(Culling Strike means enemies that are on 10% or lower life after your Hit are Killed)"]="(\"마무리 타격\"은 플레이어에게 피격되어 10% 이하의 생명력이 남은 적을 처치하는 것을 의미합니다)",
["(Debuffs you are Unaffected by can still be placed on you, but will not actually apply their effect)"]="(플레이어에게 효과가 없는 \"디버프\"는, 유지는 되겠지만 실제로 적용되지는 않습니다)",
["(Dual Wielding inherently grants +20% chance to Block Attack Damage and 10% more Attack Speed)"]="(쌍수는 기본적으로 공격 피해를 막아낼 확률 +20%를 부여하고 공격 속도를 10% 증폭시킵니다.)",
["(Each Exposure applies -10% to the matching Resistance for 4 seconds)"]="(노출 시마다 4초 간 해당 저항 -10% 적용)",
["(Each Exposure applies -10% to the matching Resistance)"]="(노출 시마다 해당 저항 -10% 적용)",
["(Each instance of Gale Force lasts 4 seconds. Maximum 10 Gale Force)"]="(강풍의 힘은 각각 4초 지속됩니다. 최대 10개까지 중첩됩니다.)",
["(Effects cannot be slowed below 25% of their normal expiry rate)"]="(정상 속도의 25% 아래로 느려질 수 없습니다)",
["(Elemental Ailments are Ignited, Scorched, Chilled, Frozen, Brittle, Shocked, and Sapped)"]="(원소 상태 이상 - 점화, 그을림, 냉각, 동결, 허약, 감전, 활력 감소)",
["(Elemental Ailments are Ignited, Scorched, Chilled, Frozen, Brittled, Shocked, and Sapped)"]="(원소 상태 이상 - 점화, 그을림, 냉각, 동결, 허약, 감전, 활력 감소)",
["(Elusive initially grants 15% chance to Avoid All Damage from Hits, and 30% increased Movement Speed. The buff reduces its effect over time, removing itself at 0% effect. If you already have an Elusive buff, you cannot gain Elusive)"]="(도피는 최초에 명중으로 인한 피해를 전부 회피할 확률 15%를 부여하고 이동 속도를 30% 증가시킵니다. 버프의 효과는 시간이 지남에 따라 0%까지 감소합니다. 이미 도피 버프를 가지고 있다면 도피를 획득할 수 없습니다)",
["(Enemies affected by Barnacles Convert 5% of Physical Damage to Cold and have 5% increased duration of Chill and Freeze on them. Each instance of Barnacles lasts 30 seconds and can be inflicted up to 10 times)"]="(따개비의 영향을 받는 적이 물리 피해의 5%를 냉기 피해로 전환하고, 적에게 걸린 냉각 및 동결의 지속시간이 5% 증가합니다. 따개비는 각각 30초 지속되고, 최대 10번 유발될 수 있습니다.)",
["(Enemies on your Brine Ground have 30% increased effect of Lightning and Cold Ailments on them and have 25% reduced Armour and Evasion Rating. Allies on your Brine Ground gain 10% of Physical Damage as extra Cold Damage and as extra Lightning Damage)"]="(플레이어의 염수 지대 위에 있는 적에게 걸린 번개 및 냉기 상태 이상의 효과가 30% 증가하고 적의 방어도와 회피가 25% 감소합니다. 플레이어의 염수 지대 위에 있는 동료는 물리 피해의 10%를 추가 냉기 피해와 추가 번개 피해로 얻습니다.)",
["(Enemies that are Debilitated have 20% less Movement Speed and deal 10% less damage)"]="(\"쇠잔\" 상태의 적은 이동 속도가 20% 감폭하고 주는 피해가 10% 감폭합니다.)",
["(Enemies you Taunt can only target you, and deal 10% less damage to anyone else. Taunt lasts for 3 seconds)"]="(\"도발\"당한 적은 플레이어만을 대상으로 하며, 다른 이에게 가하는 피해량이 10% 감폭합니다. 3초 동안 유지됩니다)",
["(Every Rage grants 1% more Attack Damage. Maximum Rage is 30. Lose 10 Rage per second if you have not been Hit or gained Rage in the last 2 seconds)"]="(격노 1당 공격 피해가 1% 증폭되며, 격노 최대치는 30입니다. 최근 2초 이내 피격되지 않았거나 격노를 얻지 못했다면 격노가 1초마다 10씩 줄어듭니다.)",
["(Every Rage has an inherent effect of 1% more Attack Damage, and modifiers can add extra effects to Rage)"]="(기본적으로 격노 하나당 공격 피해가 1% 증폭되며, 속성이 격노에 추가 효과를 부여할 수 있습니다.)",
["(Explodes when your Ward is broken, dealing Physical Spell Damage around you equal to a percentage of your Ward and inflicting Enervation on Hit, a debuff that lowers Movement Speed by 20% and prevents Life and Energy Shield Recovery for 4 seconds)"]="(수호가 깨지면 폭발하여 주위에 수호의 일정 비율과 동일한 물리 주문 피해를 주고 명중 시 피폐를 유발합니다. 피폐 디버프는 4초 동안 이동 속도를 20% 낮추고 생명력 및 에너지 보호막 회복을 막습니다.)",
["(Fanaticism grants Spells you Cast yourself 75% more Cast Speed, 75% less Cost and 75% increased Area of Effect)"]="(광신주의는 직접 시전하는 주문의 시전 속도를 75% 증폭시키고, 소모량을 75% 감폭시키며 효과 범위를 75% 증가시킴)",
["(Farrul's Farric Presence is an Aura which grants 80% increased Accuracy Rating, 120% increased Critical Strike Chance and Take no Extra Damage from Critical Hits)"]="(페룰의 페룰의 존재는 정확도를 80% 증가시키고, 치명타 확률을 120% 증가시키고, 치명타 명중으로부터 추가 피해를 받지 않게 하는 오라입니다.)",
["(Farrul's Fertile Presence is an Aura which grants 100% increased Damage, Regenerate 3% of Life per second and Cannot be Stunned)"]="(페룰의 풍요로운 존재는 피해를 100% 증가시키고, 1초마다 생명력의 3%를 재생하고, 기절하지 않게 하는 오라입니다.)",
["(Farrul's Wild Presence is an Aura which grants 20% increased Attack, Cast and Movement Speed and prevents Action Speed from being lowered below the Base Value)"]="(페룰의 황야의 존재는 공격 속도, 시전 속도, 이동 속도를 20% 증가시키고 동작 속도가 기본 수치 밑으로 낮아지지 않게 하는 오라입니다.)",
["(Fire Ailments are Ignited and Scorched)"]="(화염 상태 이상에는 점화와 그을림이 있습니다)",
["(Fire Exposure applies -10% to Fire Resistance for 4 seconds)"]="(화염 노출이 4초 간 화염 저항 -10% 적용)",
["(Fortifying grants an amount of Fortification based on the Damage of the Hit)"]="(방어 상승이 부여하는 방어 상승의 양은 명중으로 주는 피해에 기반합니다)",
["(Freeze lowers Enemy Action Speed to zero, preventing them from acting. Duration is based on the Cold Damage of the Hit)"]="(\"동결\"은 적의 동작 속도를 0으로 만들어 동작 자체를 방지합니다. 지속시간은 동결 적용 시의 냉기 피해량에 의해 결정됩니다)",
["(Freezes that would have a duration of 0.3 seconds or below are not inflicted)"]="(지속시간이 0.3초 이하인 동결이 유발되지 않음)",
["(Gain Added Spell Damage equal to the Damage of your Main Hand Weapon)"]="(주 무기 피해와 동일한 주문 피해 추가 획득)",
["(Hinder reduces movement speed by 30% for 4 seconds)"]="(\"이동 방해\"가 4초 동안 이동 속도를 30% 감소시킵니다.)",
["(Hinder reduces movement speed by 30%)"]="(\"이동 방해\"가 이동 속도를 30% 감소시킵니다.)",
["(Hinder reduces movement speed)"]="(\"이동 방해\"가 이동 속도를 감소시킵니다.)",
["(Hits against Enemies on Profane Ground have 100% increased Critical Strike Chance, and Curses have 10% increased Effect on them)"]="(부정 지대에 있는 적에 대한 저주 효과가 10% 증가하고, 해당 적들을 명중 시 적용되는 치명타 확률이 100% 증가합니다.)",
["(Hits have up to +6% Critical Strike Chance against Brittle Enemies, based on the Cold Damage of the Hit which inflicted Brittle, for 4 seconds)"]="(\"허약\" 상태의 적 명중 시 치명타 확률이 최대 +6% 증가합니다. 증가 정도는 허약을 부여한 냉기 피해에 비례합니다. 4초 동안 유지됩니다.)",
["(Hoarfrost lasts 10 seconds and can be inflicted multiple times, each refreshing the duration of existing Hoarfrost on the target. Each Hoarfost increases Freeze Duration on the target by 20%. All Hoarfrost is removed if the target is Frozen)"]="(흰서리가 10초 지속되며 여러 번 유발될 수 있습니다. 흰서리가 유발될 때마다 기존에 대상에게 유발된 흰서리의 지속시간이 초기화됩니다. 흰서리 하나당 대상에 대한 동결 지속시간이 20% 증가합니다. 대상이 동결되면 모든 흰서리를 제거합니다.)",
["(Ignite deals Fire Damage over time, based on the base Fire Damage of the Skill, for 4 seconds)"]="(\"점화\"는 지속 화염 피해를 주며, 피해량은 스킬의 기본 화염 피해량에 비례합니다. 4초 동안 지속됩니다)",
["(Ignoring Resistances means your Damage cannot be modified in any way by any Resistance stats)"]="(\"저항 무시\"는 상대가 어떤 저항을 지니고 있든 여러분에게 받는 피해량이 변하지 않음을 의미합니다)",
["(Intimidated enemies take 10% increased Attack Damage)"]="(\"위협\" 당한 적은 받는 공격 피해가 10% 증가합니다)",
["(Killing an Enemy is not Spawning a corpse)"]="(적을 처치할 때 시체를 생성하지 않습니다)",
["(Knockback pushes Enemies away when Hit)"]="(\"밀어내기\"는 피격 시 적을 뒤로 밀어냅니다)",
["(Leeched Energy Shield is recovered over time. Multiple Leeches can occur simultaneously, up to a maximum rate)"]="(\"에너지 보호막 흡수\"는 지속적으로 회복됩니다. 흡수는 최대 속도에 이를 때까지 여러 개가 동시에 적용될 수 있습니다)",
["(Leeched Life is recovered over time. Multiple Leeches can occur simultaneously, up to a maximum rate)"]="(\"생명력 흡수\"는 지속적으로 회복됩니다. 흡수는 최대 속도에 이를 때까지 여러 개가 동시에 적용될 수 있습니다)",
["(Leeched Mana is recovered over time. Multiple Leeches can occur simultaneously, up to a maximum rate)"]="(\"마나 흡수\"는 지속적으로 회복됩니다. 흡수는 최대 속도에 이를 때까지 여러 개가 동시에 적용될 수 있습니다)",
["(Life Recovery from Regeneration grants Blood Barrier while on Full Life. Maximum Blood Barrier is equal to 30% of your Maximum Life. Damage from Hits is taken from Blood Barrier before your Life or Energy Shield. 50% less Life Regeneration Rate)"]="(최대 생명력 상태일 때 재생으로 인한 생명력 회복이 피 방어막을 부여합니다. 최대 피 방어막은 최대 생명력의 30%와 동일합니다. 명중 피해가 생명력 또는 에너지 보호막보다 피 방어막에 먼저 적용됩니다. 생명력 재생 속도가 50% 감폭됩니다.)",
["(Lightning Ailments are Shocked and Sapped)"]="(번개 상태 이상에는 감전, 활력 감소가 있습니다)",
["(Lightning Exposure applies -10% to Lightning Resistance for 4 seconds)"]="(번개 노출이 4초 간 번개 저항 -10% 적용)",
["(Local Modifiers on Weapons that add damage to that Weapon do not grant you Added Damage, so are unchanged by this)"]="(무기에 붙어 무기에 피해를 추가하는 특정 속성은 추가 피해를 부여하지 않으므로, 이 변경의 영향을 받지 않습니다.)",
["(Lucky things are rolled twice and the best result used)"]="(\"행운\"은 주사위를 2회 굴린 수치 중 좋은 값을 사용하는 메커니즘입니다)",
["(Maimed enemies have 30% reduced Movement Speed)"]="(\"힘줄 절단\"된 적은 이동 속도가 30% 감소합니다)",
["(Malediction causes 10% reduced Damage dealt and 10% increased Damage taken)"]="(\"악담\" 상태에서는 주는 피해가 10% 감소하고 받는 피해가 10% 증가합니다.)",
["(Mana Burn causes you to lose 1% of your maximum Mana per stack per second)"]="(마나 연소는 1초마다 중첩당 최대 마나의 1%를 잃게 합니다.)",
["(Mania applies 4% increased Damage taken, 2% reduced Action Speed and 10% reduced Life and Energy Shield Recovery Rate for 15 seconds, and can be inflicted up to 15 times)"]="(광증은 15초 동안 받는 피해를 4% 증가시키고, 동작 속도를 2% 감소시키고, 생명력 및 에너지 보호막 회복 속도를 10% 감소시킵니다. 15회까지 중첩될 수 있습니다.)",
["(Maximum Chance to Block Attack Damage cannot be raised above 90%)"]="(공격 피해 막기 확률 최대치는 90%를 넘어갈 수 없습니다)",
["(Maximum Chance to Block Spell Damage cannot be raised above 90%)"]="(주문 피해 막기 확률 최대치는 90%를 넘어갈 수 없습니다)",
["(Maximum Resistances cannot be raised above 90%)"]="(\"저항 최대치\"는 90%를 넘어갈 수 없습니다)",
["(No chance to avoid damage can be higher than 75%)"]="(피해를 회피할 확률은 75%를 넘을 수 없습니다)",
["(Normal Monsters have 1 Power, Magic Monsters 2, Rare Monsters 10, Unique Monsters 20, and Players 5)"]="(일반 몬스터는 위세가 1, 마법 몬스터는 2, 희귀 몬스터는 10, 고유 몬스터는 20, 플레이어는 5입니다.)",
["(Only Damage from Hits can be Recouped, over 4 seconds following the Hit)"]="(피격으로 받은 피해만 회복할 수 있으며, 피격 후 4초에 걸쳐 회생)",
["(Only one Hit every 0.5 seconds can cause you to gain Rage)"]="(0.5초마다 한 번만 명중으로 격노를 획득할 수 있습니다.)",
["(Onslaught grants 20% increased Attack, Cast, and Movement Speed)"]="(\"맹공\"은 공격, 시전, 이동 속도를 20% 증가시킵니다)",
["(Overcapped Chance to Block is the amount by which Uncapped Chance to Block is higher than Maximum Chance to Block)"]="(\"제한 초과 막기 확률\"은 비 제한 막기 확률에서 막기 확률 최대치를 뺀 값입니다)",
["(Overcapped Resistance is the amount by whch Uncapped Resistance is higher than Maximum Resistance)"]="(\"제한 초과 저항\"은 비 제한 저항에서 저항 최대치를 뺀 값입니다)",
["(Overkill Damage is any Damage from a Hit in excess of the Enemy's remaining Life)"]="(\"과잉살상\" 피해는 적에게 남은 생명력을 초과해서 주는 모든 피해입니다)",
["(Passive Skills that are not Notable, Masteries, Keystones, or Jewel Sockets are Small)"]="(주요 스킬, 숙련, 핵심노드, 주얼 슬롯이 아닌 \"패시브 스킬\"은 소형으로 나타납니다)",
["(Poison deals Chaos Damage over time, based on the base Physical and Chaos Damage of the Skill. Multiple instances of Poison stack)"]="(\"중독\"은 지속 카오스 피해를 가하며, 피해량은 해당 스킬의 기본 물리 및 카오스 피해에 의해 결정됩니다. 중독은 다회 적용될 시에 중첩됩니다.)",
["(Random Shrine buffs have a base duration of 20 seconds)"]="(무작위 성소 버프가 20초의 기본 지속시간을 지님)",
["(Recently refers to the past 4 seconds)"]="(\"최근\"은 지난 4초 동안을 의미합니다)",
["(Rune Daggers are considered Daggers)"]="(룬 단검은 단검으로 간주됩니다)",
["(Sapped Enemies deal up to 20% less Damage, based on the Lightning Damage of the Hit, for 4 seconds)"]="(\"활력 감소\" 상태의 적이 가하는 피해가 최대 20% 감폭됩니다. 감폭 정도는 활력 감소를 부여한 번개 피해에 비례합니다. 4초 동안 유지됩니다)",
["(Scorched Enemies have their Elemental Resistances lowered by up to 30%, based on the Fire Damage of the Hit, for 4 seconds)"]="(\"그을린\" 적의 원소 저항이 최대 30% 감소합니다. 감소 정도는 그을림을 부여한 화염 피해에 비례합니다. 4초 동안 유지됩니다)",
["(Shock increases Damage taken by 15%)"]="(\"감전\"은 받는 피해를 15% 증가시킵니다)",
["(Shock increases Damage taken by up to 50%)"]="(\"감전\"은 받는 피해를 최대 50% 증가시킵니다)",
["(Shock increases Damage taken by up to 50%, depending on the amount of Lightning Damage in the hit, for 2 seconds)"]="(\"감전\"이 받는 피해를 2초 동안 50%까지 증가시킵니다. 증가 정도는 감전을 부여한 번개 피해량에 따라 달라집니다)",
["(Summon two Triggerbots which follow you around and run towards enemies. Your Triggered Spells Trigger twice, once from each Triggerbot's location)"]="(발동 장치를 2개 소환합니다. 발동 장치는 플레이어를 따라다니며 적을 향해 뛰어갑니다. 발동형 주문이 각 발동 장치의 위치에서 한 번씩, 두 번 발동됩니다.)",
["(Summons a Sentinel of Radiance which follows you and attacks enemies in melee, while burning enemies around it and taking a portion of damage from hits for you. You can only have one Sentinel of Radiance)"]="(플레이어를 따라다니며 적에게 근접 공격을 하는 광휘의 파수꾼을 소환합니다. 광휘의 파수꾼은 주변의 적을 불태우며 플레이어가 받는 피격 피해의 일부를 플레이어 대신 받습니다. 광휘의 파수꾼은 한 번에 하나만 보유할 수 있습니다.)",
["(Summons a spectral tiger companion that attacks nearby enemies and dies after a duration. Each spectral tiger grants you a buff that increases Critical Strike Chance, and increases Attack and Cast Speed. If you have the maximum number of them, refreshes the duration and life of an existing one instead)"]="(주변의 적들을 공격하고 일정 시간 후에 죽는 영체 호랑이 동료를 소환합니다. 각각의 영체 호랑이는 치명타 확률을 증가시키고 공격 및 시전 속도를 증가시키는 버프를 부여합니다. 이미 소환된 영체 호랑이의 수가 최대치라면 기존 영체 호랑이 1마리의 지속시간과 생명력이 초기화됩니다.)",
["(Tailwind increases Action Speed by 8%)"]="(\"순풍\"으로 동작 속도가 8% 증가합니다)",
["(Take 1% less Damage from Hits per Fortification. Maximum 20 Fortification)"]="(피격 시 받는 피해가 방어 상승 1당 1% 감폭됩니다. 방어 상승은 최대 20까지 중첩됩니다.)",
["(Take 1% less Damage from Hits per Fortification. Maximum 20 Fortification. Fortification lasts 6 seconds)"]="(피격 시 받는 피해가 방어 상승 1당 1% 감폭됩니다. 방어 상승은 최대 20까지 중첩되며 6초 지속됩니다.)",
["(The Damage Types are Physical, Fire, Cold, Lightning, and Chaos)"]="(피해 유형 - 물리, 화염, 냉기, 번개, 카오스)",
["(The Stun Threshold determines how much Damage can Stun something)"]="(\"기절 한계치\"는 기절시킬 수 있는 피해량에 의해 결정됩니다)",
["(The buff still applies to you after you leave the Banner's area)"]="(깃발의 범위에서 벗어난 후에도 버프는 여전히 적용됩니다.)",
["(The effects of the ground still apply to you, allies or enemies after leaving its area)"]="(동료 또는 적이 해당 지역을 떠난 뒤에도 플레이어는 계속 지대의 영향을 받습니다)",
["(These are consecutive)"]="(지속 효과)",
["(They will also not be put on cooldown if they remain Usable)"]="(또한 사용 가능 상태인 동안에는 재사용 대기시간이 적용되지 않습니다.)",
["(This only affects the inherent loss of Rage when you haven't been Hit or gained Rage Recently)"]="(이 효과는 최근 4초 이내 피격되지 않거나 격노를 획득하지 못한 경우 기본적으로 상실하는 격노에만 영향을 미칩니다)",
["(Throwing Mines takes 10% more time for each additional Mine thrown)"]="(추가로 투척되는 지뢰 하나당 지뢰 투척 시간이 10% 증폭됩니다)",
["(Tinctures periodically inflict Mana Burn on you while active)"]="(팅크가 활성화된 동안 주기적으로 자신에게 마나 연소 유발)",
["(Uncapped Chance to Block is the value Chance to Block would have if ignoring Maximum Chance to Block)"]="(\"비 제한 막기 확률\"은 막기 확률 최대치를 무시했을 때의 막기 확률 값입니다)",
["(Uncapped Resistance is the value Resistance would have if ignoring Maximum Resistance)"]="(\"비 제한 저항\"은 저항 최대치를 무시할 때의 저항 값입니다)",
["(Unholy Might grants 100% of Physical Damage converted to Chaos Damage and 25% chance to apply Withered on Hit)"]="(불경한 힘은 물리 피해의 100%를 카오스 피해로 전환하고 명중 시 25%의 확률로 위축을 적용하게 해줍니다)",
["(Unlucky things are rolled twice and the worst result used)"]="(\"불운\"은 주사위를 2회 굴려서 나쁜 값을 사용합니다)",
["(Unnerved enemies take 10% increased Spell Damage)"]="(\"낙담\"한 적이 받는 주문 피해가 10% 증가합니다)",
["(Up to 10 Vines can grasp you, inflicting 8% less Movement Speed per Vine. Broken by moving)"]="(최대 덩굴 10개에 사로잡힐 수 있으며, 덩굴 1개당 이동 속도가 8% 감폭됩니다. 이동 시 덩굴이 파괴됩니다)",
["(Vaal Non-Aura Skills require 80% less Souls. Vaal Non-Aura Skills require 100% increased Souls per Vaal Skill used in the past 8 seconds)"]="(비-오라 바알 스킬에 필요한 영혼이 80% 감폭되고 지난 8초 이내에 사용한 바알 스킬 하나당 비-오라 바알 스킬에 필요한 영혼이 100% 증가합니다.)",
["(Valour is gained while you have a Banner skill and augments the power of those skills)"]="(기백은 깃발 스킬을 보유한 동안 획득하며 깃발 스킬의 위력을 향상시킵니다.)",
["(Warstaves are considered Staves)"]="(전쟁지팡이는 지팡이로 간주됩니다)",
["(Weeping Wounds cause you to lose 1% of your maximum Life per second per stack. Tinctures deactivate when you have 1 life remaining)"]="(진물 나는 상처는 1초마다 중첩당 최대 생명력의 1%를 잃게 합니다. 생명력이 1 남으면 팅크가 비활성화됩니다.)",
["(When an Impaled enemy is hit, the Impale reflects 10% of the physical damage of the Impaling hit to that enemy. Impale lasts for 5 hits or 8 seconds)"]="(\"꿰뚫린\" 적이 피격당하면, 꿰뚫림이 적용되었던 타격의 물리 피해량의 10%가 적에게 반사됩니다. 꿰뚫림은 5회 피격될 동안 또는 8초 동안 유지됩니다)",
["(When you reach full Energy Shield, Sacrifice all Energy Shield to gain +5% to all Maximum Resistances for 4 seconds)"]="(에너지 보호막이 최대에 도달하면, 에너지 보호막을 모두 희생하여 4초 동안 모든 저항 최대치를 +5% 얻습니다.)",
["(While you have Phasing, your movement is not blocked by Enemies)"]="(\"차원 능력\" 상태에서는 적에 의해 이동이 가로막히지 않습니다)",
["(While you have this passive allocated, you will have the option to permanently hire Mercenaries found in the wild. Permanently hired Mercenaries and their Minions deal less Damage than temporarily hired Mercenaries, but you can change what gear they have equipped. Passives that affect your Mercenary do not affect temporarily hired Mercenaries. Permanently hired Mercenaries will only follow Luminaries with this passive allocated)"]="(이 패시브를 할당한 동안에는 황야에서 만나는 용병을 영구적으로 고용할 수 있습니다. 영구적으로 고용한 용병과 그 소환수는 일시적으로 고용한 용병보다 피해를 덜 주지만, 장비 구성을 바꿀 수 있습니다. 용병에게 영향을 미치는 패시브는 일시적으로 고용한 용병에게는 적용되지 않습니다. 영구적으로 고용한 용병은 이 패시브를 할당한 루미너리만 데리고 다닐 수 있습니다.)",
["(Wild Savagery grants 100% increased Physical Damage, 10% increased Action Speed, Hits ignore Enemy Physical Damage Reduction and Cannot be Stunned)"]="(황야의 야만성은 물리 피해와 동작 속도 100% 증가, 동작 속도 10% 증가, 명중이 적의 물리 피해 감소 무시, 기절 불가 효과를 부여합니다.)",
["(Withered applies 6% increased Chaos Damage Taken, and can be inflicted up to 15 times)"]="(\"위축\"은 받는 카오스 피해를 6% 증가시킵니다. 15회까지 중첩될 수 있습니다)",
["(You are Unencumbered while you have no Gloves, no Main Hand Item, and no Off Hand Item Equipped)"]="(장갑, 주 무기 그리고 보조 장비를 장착하지 않는 동안 \"홀가분\" 상태가 됩니다)",
["(You are in Blood Stance by default)"]="(플레이어는 기본적으로 핏빛 태세를 취합니다)",
["(You are on Low Life if you have 50% of your Maximum Life or less)"]="(생명력이 최대 생명력의 50% 이하일 때가 \"낮은 생명력\" 상태입니다)",
["(You can only take one of the three Duelist Ascendancy passives)"]="(세 개의 듀얼리스트 전직 직업 중 하나만 선택할 수 있습니다)",
["(You can only take one of the three Marauder Ascendancy passives)"]="(세 개의 머라우더 전직 직업 중 하나만 선택할 수 있습니다)",
["(You can only take one of the three Ranger Ascendancy passives)"]="(세 개의 레인저 전직 직업 중 하나만 선택할 수 있습니다)",
["(You can only take one of the three Shadow Ascendancy passives)"]="(세 개의 쉐도우 전직 직업 중 하나만 선택할 수 있습니다)",
